window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"uDX-Gcas9yc","speaker":"Mohamed Ali Nafti","role":"Foreign Minister","country":"Tunisia","region":"Middle East","url":"https://www.youtube.com/watch?v=uDX-Gcas9yc","date":"20260926","title":"🇹🇳 Tunisia - Foreign Minister Addresses United Nations General Debate, 81st Session | #UNGA","seconds":1652,"words":3155,"counts":{"claims":38,"promises":0,"attacks":2},"topics":[{"topic":"UN reform","share":0.2796,"seconds":462},{"topic":"Palestine","share":0.0942,"seconds":156},{"topic":"Libya","share":0.0783,"seconds":129},{"topic":"Israel-Gaza","share":0.0741,"seconds":122},{"topic":"Tunisia migration","share":0.0545,"seconds":90},{"topic":"Tunisia diaspora","share":0.0545,"seconds":90},{"topic":"Protection of civilians","share":0.053,"seconds":88},{"topic":"AI governance","share":0.0473,"seconds":78},{"topic":"Tunisia human rights","share":0.0446,"seconds":74},{"topic":"Africa development","share":0.0443,"seconds":73},{"topic":"Climate finance","share":0.0433,"seconds":72},{"topic":"Tunisia multilateralism","share":0.0429,"seconds":71},{"topic":"Tunisia peacekeeping","share":0.038,"seconds":63},{"topic":"Syria Sudan Yemen","share":0.0375,"seconds":62},{"topic":"Ceremony","share":0.0138,"seconds":23}],"timeline":[[2,67,"UN reform"],[69,130,"UN reform"],[134,195,"UN reform"],[197,268,"Tunisia multilateralism"],[271,342,"UN reform"],[343,405,"UN reform"],[405,486,"UN reform"],[487,549,"Israel-Gaza"],[550,611,"Israel-Gaza"],[612,702,"Palestine"],[703,768,"Palestine"],[770,832,"Libya"],[833,900,"Libya"],[901,963,"Syria Sudan Yemen"],[964,1037,"Africa development"],[1039,1102,"Tunisia peacekeeping"],[1103,1164,"UN reform"],[1165,1255,"Tunisia migration"],[1255,1327,"Climate finance"],[1328,1406,"AI governance"],[1407,1480,"Tunisia human rights"],[1482,1572,"Tunisia diaspora"],[1573,1660,"Protection of civilians"],[1661,1684,"Ceremony"]],"stances":{"UN reform":"Mohamed Ali Nafti congratulates Mr. Khalil Rahman on his election as president of the 81st session of the general assembly and wishes him success.","Tunisia multilateralism":"Mohamed Ali Nafti states that Tunisia's belief in multilateral action is a long-standing conviction rooted in its history of struggle for sovereignty and self-determination.","Israel-Gaza":"Tunisia condemns Israeli settlement policies and actions in Gaza, calling for international accountability to end the suffering.","Palestine":"Tunisia rejects unilateral measures altering Jerusalem and calls for humanitarian aid while defending UNRWA's mandate.","Libya":"Tunisia calls for an immediate cessation of military operations in the region and reaffirms its commitment to freedom of navigation while emphasizing shared interests with Libya.","Syria Sudan Yemen":"Mohamed Ali Nafti expresses hope for Syria's unity, calls for an end to the war in Sudan, and supports a political settlement in Yemen.","Africa development":"Tunisia reaffirms its commitment to African solutions for African problems and supports the reform of the African Union.","Tunisia peacekeeping":"Tunisia emphasizes its determination to continue contributing to peacekeeping efforts in Africa and strengthen economic integration on the continent.","Tunisia migration":"Tunisia rejects becoming a transit or destination country for irregular migrants and emphasizes efforts to save lives, provide care, and support voluntary returns while combating trafficking.","Climate finance":"Tunisia advocates for reforming the international financial architecture to ensure equitable access to financing and reduce debt burdens for developing countries.","AI governance":"Tunisia supports AI development but requires global governance to prevent widening the digital divide.","Tunisia human rights":"Tunisia reaffirms its commitment to human rights, public freedoms, and the empowerment of women and youth in accordance with its constitution and international obligations.","Tunisia diaspora":"Mohamed Ali Nafti commends the Tunisian diaspora for enhancing Tunisia's image and supporting development, reaffirming the president's commitment to strengthening support programs and ties with them.","Protection of civilians":"Tunisia advocates for collective responsibility and humanitarian imperatives to protect civilians, including through an international platform and unified operational manuals.","Ceremony":"Mohamed Ali Nafti expresses gratitude for the audience's attention and thanks a colleague for their presentation."},"claims":[{"t":52,"quote":"I would like to extend my sincere congratulations to his excellency Mr. Khalil Rahman on his election as president of the 81st session of the general assembly.","topic":"UN reform","kind":"fact"},{"t":80,"quote":"wise leadership in the service of peace, security, development and justice and for his tireless efforts to preserve the standing of the organization and restore confidence in multilateral action at a time of extraordinary international when maintaining the effectiveness of the United Nations has become a demanding responsibility. and an almost daily challenge.","topic":"UN reform","kind":"fact"},{"t":111,"quote":"Mr. Guteres faced with courage and dedication unprecedented global crisis.","topic":"UN reform","kind":"fact"},{"t":134,"quote":"At this critical historical juncture for the United Nations, we look forward with great hope to the selection through the process of electing the new secretary general","topic":"UN reform","kind":"fact"},{"t":256,"quote":"Following independence, Tunisia engaged fully within the United Nations to complete the foundations of its sovereignty and to build the modern state and it succeeded in doing so.","topic":"Tunisia multilateralism","kind":"fact"},{"t":271,"quote":"Restoring confidence in the organization and in multilateral action requires in our view two essential conditions. A genuine commitment and a meaningful reform process.","topic":"UN reform","kind":"fact"},{"t":284,"quote":"First, there must be a sincere determination and responsible commitment by all states to respect international law founded on agreement and the principle of sovereign equality among states","topic":"UN reform","kind":"fact"},{"t":390,"quote":"Tunisia welcomes the the efforts undertaken within the framework of the UN80 initiative.","topic":"UN reform","kind":"fact"},{"t":405,"quote":"We support the three reform tracks proposed by the initiative provided that they are pursued through an inclusive consultative process that preserves the intergovernmental nature of the organization and does not undermine the negotiating mandates of member states.","topic":"UN reform","kind":"fact"},{"t":424,"quote":"Tunisia also believes that addressing the liquidity crisis in the organization requires all states to meet their financial obligations in full.","topic":"UN reform","kind":"fact"},{"t":489,"quote":"Palestinian people are subjected daily to the most horrific crimes and violations and denied their most basic rights to life, security, freedom","topic":"Israel-Gaza","kind":"fact"},{"t":529,"quote":"crimes of genocide that claim more lives each day","topic":"Israel-Gaza","kind":"fact"},{"t":552,"quote":"the court of international court of justice in its advisory opinion of the 19th of July 2024 affirmed that the occupying entity is compelled to end its unlawful presence in the occupied Palestinian territory","topic":"Israel-Gaza","kind":"fact"},{"t":566,"quote":"all UN member states are likewise compelled not to recognize as lawful the situation resulting from that unlawful presence","topic":"Israel-Gaza","kind":"fact"},{"t":624,"quote":"forc displacement, house demolitions, and repeated attacks on Islamic and Christian holy sites, the catastrophic humanitarian conditions endured by the Palestinian people, particularly in the Gaza Strip.","topic":"Palestine","kind":"fact"},{"t":641,"quote":"As a result of continued casualties, displacement, the destruction of homes and infrastructure, and the collapse of the health care system require safe, urgent, and sustained humanitarian","topic":"Palestine","kind":"fact"},{"t":710,"quote":"The will of peoples always finds its way and ultimately prevails. Such is the law of the universe and the course of history.","topic":"Palestine","kind":"fact"},{"t":733,"quote":"For most among them, their right to establish an independent and fully sovereign state on the entirety of Palestine with Al Sharif as its capital.","topic":"Palestine","kind":"fact"},{"t":770,"quote":"Tuneshar renews its call for an immediate sessation of military operations, for wisdom and reason to prevail, and for a return to dialogue and giving absolute priority to political and peaceful and diplomatic solutions as the only means of resolving existing disputes in a manner that strengthens the foundations of security and stability in the region and prevents further escalation.","topic":"Libya","kind":"fact"},{"t":798,"quote":"Tunisia also reaffirms its commitment to freedom of navigation and maritime security in accordance with the principles and provisions of the UN convention on the law of the sea and customary international law while preserving global energy security international supply chains and the economic rights of states.","topic":"Libya","kind":"fact"},{"t":833,"quote":"Tunisia supports every sincere Libyan effort and every serious UN initiative aimed at ending the crisis on the basis of a Libyanled and Libyanowned solution founded on dialogue and consensus among all parties preserving Libya's unity, sovereignty, territorial integrity and the aspirations of the brotherly Libyan people for security, stability and a unified state","topic":"Libya","kind":"fact"},{"t":870,"quote":"We are committed to Lebanon's sovereignty and independence and we condemn the repeated violations of the ceasefire agreement in this brotherly country in a flagrant violation of UN resolutions.","topic":"Libya","kind":"fact"},{"t":913,"quote":"Tunisia follows with grave concern the continue continuing war in Sudan","topic":"Syria Sudan Yemen","kind":"fact"},{"t":966,"quote":"The abundant human resources, natural wealth, and the promising potential of Africa make Africa an essential partner in advancing development at the international level.","topic":"Africa development","kind":"fact"},{"t":979,"quote":"Yet, Africa, the Africa we want, continues to face intertwined security and economic challenges that require a comprehensive approach.","topic":"Africa development","kind":"fact"},{"t":1047,"quote":"a commitment it has maintained since the first years of its independence","topic":"Tunisia peacekeeping","kind":"fact"},{"t":1104,"quote":"ensuring that everyone benefits from the UN while directing greater support and to those in greatest need and to the peoples and countries facing war, poverty, marginalization, and the effects of global crisis.","topic":"UN reform","kind":"fact"},{"t":1177,"quote":"Such an approach would embody shared responsibility, solidarity, and cooperation among countries of origin, transit, and destination.","topic":"Tunisia migration","kind":"fact"},{"t":1186,"quote":"In this context, the Tunisian authorities continue their efforts to save the lives of of irregular migrants on land and at sea, provide them with care, and create suitable conditions for their voluntary return to their countries of origin in coordination with the International Organization for Migration while safeguarding their dignity and rights and combating human and migrant and smuggling and also supporting them once they are back in their countries of origin.","topic":"Tunisia migration","kind":"fact"},{"t":1255,"quote":"bear severe consequences despite their limited historical responsibility for emissions.","topic":"Climate finance","kind":"fact"},{"t":1265,"quote":"countries with the greatest responsibility must fulfill their commitments regarding climate finance while maintaining a clear distinction between climate financing and development financing.","topic":"Climate finance","kind":"fact"},{"t":1329,"quote":"rapid development of artificial intelligence offers great opportunities to accelerate development goals provided that it is accompanied by comprehensive and equitable global governance","topic":"AI governance","kind":"fact"},{"t":1368,"quote":"reform process launched on the 25th of July 2021 with the aim of consolidating a democracy that guarantees rights and freedoms for all citizens","topic":"AI governance","kind":"fact"},{"t":1409,"quote":"Tunesha reaffirms its steadfast commitment to human rights and public and individual freedoms in accordance with the constitution of the 25th of July 2022","topic":"Tunisia human rights","kind":"fact"},{"t":1423,"quote":"We stress the importance of promoting the comprehensive and interconnected nature of human rights including economic, climate related, social, scientific, cultural and educational rights","topic":"Tunisia human rights","kind":"fact"},{"t":1482,"quote":"I also take this opportunity to commend all members of the Tunisian diaspora wherever they may be in recognition of their role in enhancing Tunisia's image abroad and supporting development efforts in their homeland.","topic":"Tunisia diaspora","kind":"fact"},{"t":1500,"quote":"We reaffirm the president's continuous commitment to strengthening support programs for the diaspora and further consolidating ties with them so that our diaspora may continue to serve as a living example of successful integration in their countries of presidents.","topic":"Tunisia diaspora","kind":"fact"},{"t":1581,"quote":"Tunisia calls for building upon the outcomes of the international conference hosted by Tunisia in July 2025 in cooperation with the UN Department of Peace Peace Operations on the role of armed forces in the protection of civilians","topic":"Protection of civilians","kind":"fact"}],"promises":[],"attacks":[{"t":518,"quote":"continuing settlement policies of the occupying entity in the West Bank and the policies of persecution, starvation, and isolation in the Gaza Strip","topic":"Israel-Gaza","target":"Israel"},{"t":890,"quote":"condemns the repeated Zionist attacks targeting the Syrian territory and the resources of the brotherly Syrian people","topic":"Libya","target":"Israel"}],"greece":[],"said":[],"pickup":[],"transcript":[{"t":2,"topic":"UN reform","text":"I now give the floor to his excellency Muhammad Ali Nafti, for Foreign Affairs, Migration and Tunisians Abroad of Tunisia. In the name of God most merciful, most May the peace of God be upon you. Mr. President, your excellencies, ladies and At the outset, I would like to extend my sincere congratulations to his excellency Mr. Khalil Rahman on his election as president of the 81st session of the general assembly. I wish him every success in leading the work of this session."},{"t":69,"topic":"UN reform","text":"I would also like to express our deep appreciation and gratitude to the secretary general Mr. Antonio Guterish at the end of his term of office for his wise leadership in the service of peace, security, development and justice and for his tireless efforts to preserve the standing of the organization and restore confidence in multilateral action at a time of extraordinary international when maintaining the effectiveness of the United Nations has become a demanding responsibility. and an almost daily challenge. Mr. Guteres faced with courage and dedication unprecedented global crisis. He leaves behind a significant legacy of committed diplomacy and principled that we shall continue to remember."},{"t":134,"topic":"UN reform","text":"At this critical historical juncture for the United Nations, we look forward with great hope to the selection through the process of electing the new secretary general of the most capable and deserving individual to lead the organization with a bold strategic vision. Building upon the efforts of his predecessor and capable of providing practical solutions for the various regions whose peoples continue to suffer the consequences of crisis, wars, instability and inequality. A vision that restores hope to future generations for a better future in which the conditions for a dignified life are available to all. Mr. President, we meet during this 81st session under the theme restoring trust and managing transformation, a United Nations that delivers for all."},{"t":197,"topic":"Tunisia multilateralism","text":"This prompt us to ask how can we restore this trust and before managing the desired transformation, how can we create the conditions and lay the foundations necessary for it? Our questions stem neither from doubt nor from pessimism, but from a firm conviction that restoring trust requires serious and responsible reflection on the reasons behind its decline. Tunisia's belief in multilateral action is not a product of current circumstances. Rather, it is the continuation of a journey that began before independence when the national movement brought the cause of the Tunisian people before the United and made the right to self-determination and the recovery of sovereignty, an integral part of the struggle for freedom. Following independence, Tunisia engaged fully within the United Nations to complete the foundations of its sovereignty and to build the modern state and it succeeded in doing so."},{"t":271,"topic":"UN reform","text":"Restoring confidence in the organization and in multilateral action requires in our view two essential conditions. A genuine commitment and a meaningful reform process. First, there must be a sincere determination and responsible commitment by all states to respect international law founded on agreement and the principle of sovereign equality among states and to uphold the purposes and principles of the UN charter, particularly refraining from the use of force, the settlement of disputes by peaceful means, and fulfilling international obligations in good faith. Second, the United Nations must embark on a comprehensive and profound reform process that responds to the transformations that have taken place in the world. This requires in particular reconsidering the mechanisms of decision making within the organization to ensure a more balanced and equitable geographical representation and establishing more effective mechanisms for transparency and accountability."},{"t":343,"topic":"UN reform","text":"Thus reinforcing the confidence of states and peoples in the organization's ability to respond to the aspirations of all. Unless genuine progress is achieved on these two tracks, collective action will remain hostage to narrow geopolitical calculations and the gap will continue to to widen between the principles we agree upon and the realities we witness on the ground. We may choose either to continue meeting under the idealism of slogans or to commit ourselves to what can truly achieve development, prosperity and peace for all. If we have the will, we have the capacity. Tunisia welcomes the the efforts undertaken within the framework of the UN80 initiative. We regard these efforts as a true opportunity on which we should build rather than a final destination in the reform process."},{"t":405,"topic":"UN reform","text":"We support the three reform tracks proposed by the initiative provided that they are pursued through an inclusive consultative process that preserves the intergovernmental nature of the organization and does not undermine the negotiating mandates of member states. Tunisia also believes that addressing the liquidity crisis in the organization requires all states to meet their financial obligations in full. We stress that reform should not result in a reduction of support allocated to developing countries or to humanitarian missions and development programs supervised by the organization and a specialized agencies. Tunisia therefore calls for a fair and balanced approach that safeguards both the effectiveness and credibility of the United Nations. Mr. President trust in the international system is measured by the extent to which its members adhere to the principles of the charter and its resolutions and by the organization's ability to ensure respect for international law without selectivity or double standards and to the oppressed peoples who have no refuge except international legitimacy."},{"t":487,"topic":"Israel-Gaza","text":"How can we restore distrust while the Palestinian people are subjected daily to the most horrific crimes and violations and denied their most basic rights to life, security, freedom, and While the international community remains unable to put an end to their ongoing humanitarian suffering or to enforce respect for international law and international humanitarian law. My country, Tunisia, condemns the continuing settlement policies of the occupying entity in the West Bank and the policies of persecution, starvation, and isolation in the Gaza Strip and the the crimes of genocide that claim more lives each day. In the absence of any accountability or any punishment, Tunisia calls upon the international community to shoulder its legal, moral and humanitarian responsibilities and to end this long-standing historical injustice."},{"t":550,"topic":"Israel-Gaza","text":"Tuneshar recalls that the court of international court of justice in its advisory opinion of the 19th of July 2024 affirmed that the occupying entity is compelled to end its unlawful presence in the occupied Palestinian territory and that all UN member states are likewise compelled not to recognize as lawful the situation resulting from that unlawful presence and that the United Nations through its principal organs should consider the means and measures required to bring that presence to an end as rapidly as We further recall that the international court of justice in the same advisory opinion determined that the policies pursued by the occupying entity in Jerusalem form part of the process of and affirmed that the domestic law of the occupying power does not alter Jerusalem's international legal status."},{"t":612,"topic":"Palestine","text":"In this context, Tunisia reiterates its categorical rejection of all unilateral measures aimed at altering the historical, legal, and demographic character of holy Jerusalem, including forc displacement, house demolitions, and repeated attacks on Islamic and Christian holy sites, the catastrophic humanitarian conditions endured by the Palestinian people, particularly in the Gaza Strip. As a result of continued casualties, displacement, the destruction of homes and infrastructure, and the collapse of the health care system require safe, urgent, and sustained humanitarian It also requires allowing the UN and its specialized agencies to carry out their the UN relief and works agency for Palestine refugees in the near east. Tunesha considers that any attempt to dismantle this longstanding UN agency or to undermine its mandate prior to a just and lasting solution to the Palestinian refugee issue constitutes a desperate attempt to eliminate the right of return and to liquidate the Palestinian cause as a The logic of force may be able to impose a bitter and inhumane reality for a period of time,"},{"t":703,"topic":"Palestine","text":"but it can never break the will of peoples nor halt the course of history. The will of peoples always finds its way and ultimately prevails. Such is the law of the universe and the course of history. Tunisia will remain steadfast in its support for the legitimate rights of the Palestinian people which are not subject to prescription. For most among them, their right to establish an independent and fully sovereign state on the entirety of Palestine with Al Sharif as its capital. Mr. President Tunisha Tunisia follows with deep concern the continuing escalation in the Middle East and its dangerous repercussions at the security, political and economic levels. Tuna believes that the continuation of the situation will further complicate matters and could lead to catastrophic consequences for all countries of the region and the world."},{"t":770,"topic":"Libya","text":"Tuneshar renews its call for an immediate sessation of military operations, for wisdom and reason to prevail, and for a return to dialogue and giving absolute priority to political and peaceful and diplomatic solutions as the only means of resolving existing disputes in a manner that strengthens the foundations of security and stability in the region and prevents further escalation. Tunisia also reaffirms its commitment to freedom of navigation and maritime security in accordance with the principles and provisions of the UN convention on the law of the sea and customary international law while preserving global energy security international supply chains and the economic rights of states. Mr. President given the bonds of brotherhood and good neighborliness that unite the Tunisian and Libyan peoples as well as their share shared interests and common destiny."},{"t":833,"topic":"Libya","text":"Tunisia supports every sincere Libyan effort and every serious UN initiative aimed at ending the crisis on the basis of a Libyanled and Libyanowned solution founded on dialogue and consensus among all parties preserving Libya's unity, sovereignty, territorial integrity and the aspirations of the brotherly Libyan people for security, stability and a unified state Tunisia reiterates its full solidarity with the Lebanese Republic and stands by the Lebanese people. We are committed to Lebanon's sovereignty and independence and we condemn the repeated violations of the ceasefire agreement in this brotherly country in a flagrant violation of UN resolutions. Tunisia calls for the United Nations to be enabled to fully discharge its mandate in the brotherly country of Lebanon. Tunisia also condemns the repeated Zionist attacks targeting the Syrian territory and the resources of the brotherly Syrian people."},{"t":901,"topic":"Syria Sudan Yemen","text":"We express our hope that the Syrian people will succeed in preserving the unity, independence, and sovereignty of Syria over all its territory. Likewise, Tunisia follows with grave concern the continue continuing war in Sudan and we renew our solidarity with the Sudan people. Tunisia calls upon the United Nations to support all efforts aimed at achieving an immediate and permanent sessation of hostilities in the hope that Sudan may restore stability and security, turn the page on conflict, and focus on reconstruction and recovery. Tunisia also hopes that the Yemeni brothers will reach a comprehensive and lasting political settlement that restores security and stability to the Yemeni people and preserve the country's territorial integrity. Tuneshar renews its support for regional and international efforts to find a solution to the crisis in Yemen."},{"t":964,"topic":"Africa development","text":"Mr. president. The abundant human resources, natural wealth, and the promising potential of Africa make Africa an essential partner in advancing development at the international level. Yet, Africa, the Africa we want, continues to face intertwined security and economic challenges that require a comprehensive approach. In this regard, Tunisia reaffirms its commitment to the principle of African solutions to African problems, thereby strengthening the ownership of African countries and peoples over the resolution of their crisis and reinforcing the role of African mechanisms and institutions in maintaining peace and security. Tuneshar renews its support for the reform of the African Union so that it may better fulfill its responsibilities and respond effectively to current Tunisia also stresses the importance of strengthening the partnership between the United Nations and the African Union in confl conflict prevention, mediation, peace building and sustainable development."},{"t":1039,"topic":"Tunisia peacekeeping","text":"In this context, Tunisia emphasizes its determination to continue contributing to peacekeeping efforts in Africa, a commitment it has maintained since the first years of its independence. Tunisia also reiterates its commitment to strengthen economic integration across the continent particularly within the common market for eastern and southern Africa ksa and the African continental free trade Mr. President, Tunisia believes that peace, security and comprehensive development are inseparable. The essence of this session, a United Nations that delivers for all, lies in the organization's ability to serve all states and peoples according to their needs and commensurate to the challenges they face. Equality does not mean identical responses."},{"t":1103,"topic":"UN reform","text":"Rather, it means ensuring that everyone benefits from the UN while directing greater support and to those in greatest need and to the peoples and countries facing war, poverty, marginalization, and the effects of global crisis. The United Nations we seek is one that leaves no one behind, does not define need according to selective political criteria and places justice, equity, and solidarity at the core of its services to all. Guided by its firm belief in the importance of investing in people, Tunisia once again calls for a comprehensive and balanced approach to that takes into account its human and historical dimensions and moves beyond a narrow security perspective while addressing its root causes."},{"t":1165,"topic":"Tunisia migration","text":"Foremost among them conflict, poverty, economic and social disparities, lack of employment opportunities and development, and the proliferation of human trafficking networks. Such an approach would embody shared responsibility, solidarity, and cooperation among countries of origin, transit, and destination. In this context, the Tunisian authorities continue their efforts to save the lives of of irregular migrants on land and at sea, provide them with care, and create suitable conditions for their voluntary return to their countries of origin in coordination with the International Organization for Migration while safeguarding their dignity and rights and combating human and migrant and smuggling and also supporting them once they are back in their countries of origin. Tunisia once again firmly rejects becoming either a transit country or a destination for irregular migrants who are victims of human trafficking Believing that climate change is a major factor affecting development, security and stability, Tunisia emphasizes that addressing this challenge requires a genuine climate particularly since developing countries"},{"t":1255,"topic":"Climate finance","text":"bear severe consequences despite their limited historical responsibility for emissions. countries with the greatest responsibility must fulfill their commitments regarding climate finance while maintaining a clear distinction between climate financing and development financing. Tunisia believes that achieving climate justice, comprehensive development and pandemic preparedness and response requires reform of the international financial architecture to make it more equitable, inclusive and fair. Thus, ensuring developing countries have easier and fairer access to financing. and enabling them to invest in scientific research, technology, innovation and digital transformation, thereby reducing their debt burdens, strengthening their resilience and empowering them to relying on their own capacities and shaming shaping their future."},{"t":1328,"topic":"AI governance","text":"My country stresses that the rapid development of artificial intelligence offers great opportunities to accelerate development goals provided that it is accompanied by comprehensive and equitable global governance that ensure that responsible use and prevents the widening of the digital divide between north and south through capacity building, technology transfer and adequate financing. Mr. Mr. President, under the leadership leadership of President Kaiside, Tunisia reaffirms its unwavering determination to continue its reform process launched on the 25th of July 2021 with the aim of consolidating a democracy that guarantees rights and freedoms for all citizens and responds to the aspirations of the Tunisian Tunisian people for development and prosperity. My country relies primarily on its own resources and human potential and remains committed to attracting investment, strengthening and diversifying economic partnerships based on mutual benefit, equality and mutual respect in a manner that serves it its interests and preserves the independence of its decision making."},{"t":1407,"topic":"Tunisia human rights","text":"In this cont context, Tunesha reaffirms its steadfast commitment to human rights and public and individual freedoms in accordance with the constitution of the 25th of July 2022, its international obligations and the choices of its people. We stress the importance of promoting the comprehensive and interconnected nature of human rights including economic, climate related, social, scientific, cultural and educational rights. foremost among them the fundamental right to development. We believe that the success of reform and development depends on the participation of women and youth. Therefore, Tunisia emphasizes its commitment to strengthening the role of women in public life and in decision-making positions and to continuing efforts to combat all forms of violence and discrimination against women. Recognizing that women's empowerment is a key driver of development and stability. Likewise, Tunisia places youth at the heart of its national priorities and works to empower them politically, economically and socially while encouraging their initiatives and their participation in public affairs and decision making."},{"t":1482,"topic":"Tunisia diaspora","text":"I also take this opportunity to commend all members of the Tunisian diaspora wherever they may be in recognition of their role in enhancing Tunisia's image abroad and supporting development efforts in their homeland. We reaffirm the president's continuous commitment to strengthening support programs for the diaspora and further consolidating ties with them so that our diaspora may continue to serve as a living example of successful integration in their countries of presidents. Mr. President Tunisia firmly believes that peace operations cannot be limited to crisis management and conflict Rather, they must contribute to creating conditions conducive to sustainable through supporting state institutions, the rule of law, the empowerment of local communities, and enhancing Tunisia reaffirms its readiness to continue contributing to the development of the peacekeeping system in ways that enhance its effectiveness and Drawing on our long-standing and active participation in UN peacekeeping operations, Tunisia believes that advancing these operations requires investment in human and institutional"},{"t":1573,"topic":"Protection of civilians","text":"capacities and a greater protection of civilians as a collective responsibility and humanitarian imperative. In this regard, Tunisia calls for building upon the outcomes of the international conference hosted by Tunisia in July 2025 in cooperation with the UN Department of Peace Peace Operations on the role of armed forces in the protection of civilians, including through the establishment of an international platform for exchanging expertise and information, the development of a unified operational manual, and the strengthening of training, capacity building and civil military coordination which should include both men and women. Mr. in conclusion, I wish to reaffirm that the United Nations remains for Tunisia the home of international legitimacy, the house that carries the hopes and aspirations of h future generations for a more just and equitable international order and a unique forum for finding practical solutions to achieve the balance of peace, security, and comprehensive and sustainable development in accordance with the UN 2030 agenda."},{"t":1661,"topic":"Ceremony","text":"I thank you for your kind attention. May the peace and mercy of God be upon you. I thank the Minister for Foreign and Tunisians Abroad for his presentation."}],"compare":[{"topic":"UN & its reform","share":0.2836,"mean":0.2043,"rank":53,"others":170},{"topic":"Israel–Palestine","share":0.1707,"mean":0.0518,"rank":14,"others":76},{"topic":"Libya","share":0.0794,"mean":0.0024,"rank":3,"others":5},{"topic":"Human Rights","share":0.0538,"mean":0.0084,"rank":13,"others":24},{"topic":"Artificial Intelligence","share":0.048,"mean":0.0505,"rank":80,"others":83},{"topic":"Africa","share":0.0449,"mean":0.0233,"rank":36,"others":36},{"topic":"Climate Change","share":0.0439,"mean":0.0428,"rank":76,"others":77},{"topic":"Syria","share":0.038,"mean":0.0033,"rank":7,"others":7}]};
